INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('3c5ad66f-3af6-43a7-a225-7aa6f232da86', 'c3c3c3c3-3030-4000-8000-000000000003', 18, 'Dia 18 — Paciência', 'Semana 3: Discernir', '{"pch": "A perseveran\u00e7a tenha obra perfeita\u2026 Clareza raramente \u00e9 instant\u00e2nea. \u00c0s vezes, esperar \u00e9 a resposta.", "verse": "Tg 1,4", "lectio": "Leia Tg 1,2-4. Alegria nas prova\u00e7\u00f5es.", "practice": "Espere antes de responder algo hoje. Observe o que muda.", "question": "Em que \u00e1rea da vida voc\u00ea precisa de mais paci\u00eancia?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;